<?php
session_start();require_once 'conexao.php';require_once 'includes/flash.php';require_once 'includes/validation.php';
function voltar($m){global $nome,$telefone,$nascimento;$_SESSION['form_old']=['nome'=>$nome??'','telefone'=>$telefone??'','nascimento'=>$nascimento??''];flash('error',$m);header('Location: agendamento.php');exit;}
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: agendamento.php');exit;}
$nome=trim($_POST['nome']??'');$telefone=somenteDigitos($_POST['telefone']??'');$nascimento=$_POST['nascimento']??'';$servico=trim($_POST['servico']??'');$pid=(int)($_POST['profissional_id']??0);$data=$_POST['data']??'';$horario=$_POST['horario']??'';$lembreteOpcao=$_POST['lembrete_opcao']??'60';$lembreteMinutos=0;if($lembreteOpcao==='custom'){$lv=max(1,(int)($_POST['lembrete_valor']??1));$lu=$_POST['lembrete_unidade']??'horas';$lembreteMinutos=$lu==='horas'?$lv*60:$lv;}else{$lembreteMinutos=max(0,(int)$lembreteOpcao);}if($lembreteMinutos>10080)$lembreteMinutos=10080;$servicos=['Psicoterapia','Fonoterapia infantil','Nutrição','Nutrição Bioimpedanciometria','Clínica geral'];
if(mb_strlen($nome)<3)voltar('Informe o nome completo.');if(!telefoneValido($telefone))voltar('Informe um telefone válido com 10 dígitos para fixo ou 11 para celular.');if(!in_array($servico,$servicos,true)||!$pid)voltar('Selecione serviço e profissional.');
$dn=DateTime::createFromFormat('!Y-m-d',$nascimento);if(!$dn||$dn->format('Y-m-d')!==$nascimento||$nascimento>date('Y-m-d'))voltar('Informe uma data de nascimento válida.');$d=DateTime::createFromFormat('!Y-m-d',$data);if(!$d||$d->format('Y-m-d')!==$data||$data<date('Y-m-d'))voltar('Escolha uma data válida.');if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$horario))voltar('Escolha um horário válido.');
try{$s=$pdo->prepare('SELECT id FROM profissionais WHERE id=? AND ativo=1');$s->execute([$pid]);if(!$s->fetch())voltar('Profissional indisponível.');$dia=(int)$d->format('w');$s=$pdo->prepare('SELECT COUNT(*) FROM disponibilidades WHERE profissional_id=? AND data=? AND horario=? AND ativo=1');$s->execute([$pid,$data,$horario.':00']);$ok=(int)$s->fetchColumn();if(!$ok){$s=$pdo->prepare('SELECT COUNT(*) FROM horarios_profissionais WHERE profissional_id=? AND dia_semana=? AND horario=? AND ativo=1');$s->execute([$pid,$dia,$horario.':00']);$ok=(int)$s->fetchColumn();}if(!$ok)voltar('Este horário não está disponível.');$pdo->beginTransaction();$s=$pdo->prepare("SELECT id FROM agendamentos WHERE profissional_id=? AND data=? AND horario=? AND status IN ('agendado','confirmado') FOR UPDATE");$s->execute([$pid,$data,$horario.':00']);if($s->fetch()){ $pdo->rollBack();voltar('Este horário acabou de ser ocupado. Escolha outro.');}$token=bin2hex(random_bytes(24));$s=$pdo->prepare("INSERT INTO agendamentos(nome,telefone,nascimento,servico,profissional_id,data,horario,status,token,paciente_id,lembrete_minutos) VALUES(?,?,?,?,?,?,?,'agendado',?,?,?)");$s->execute([$nome,$telefone,$nascimento,$servico,$pid,$data,$horario.':00',$token,!empty($_SESSION['paciente_id'])?(int)$_SESSION['paciente_id']:null,$lembreteMinutos]);$id=$pdo->lastInsertId();$pdo->commit();unset($_SESSION['form_old']);header('Location: sucesso.php?id='.$id);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();voltar('Não foi possível concluir o agendamento. Tente novamente.');}
